class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []          # options in insertion order
        self.votes = {}            # option -> vote count
        self.voters = set()        # voters who have voted
        self.total_votes = 0

    def add_option(self, option: str) -> None:
        if option not in self.votes:
            self.options.append(option)
            self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self.voters:
            raise ValueError(f"Voter {voter!r} has already voted")
        if option not in self.votes:
            raise ValueError(f"Option {option!r} does not exist")
        self.voters.add(voter)
        self.votes[option] += 1
        self.total_votes += 1

    def winner(self) -> str | None:
        if self.total_votes < 3:
            return None
        # Iterate in insertion order so later-added options win ties.
        best = None
        for option in self.options:
            if best is None or self.votes[option] >= self.votes[best]:
                best = option
        return best
